+    int x = rect->x;
+    int y = rect->y;
+    int width = rect->w;
+    int height = rect->h;
+    int max_x, max_y;
+
+    if (x < 0)
+    {
+        width += x;
+        x = 0;
+    }
+
+    if (y < 0)
+    {
+        height += y;
+        y = 0;
+    }
+
+    max_x = surface->w;
+    max_y = surface->h;
+
+    if (x + width > max_x)
+        width = max_x - x;
+
+    if (y + height > max_y)
+        height = max_y - y;
+
+    if (width <= 0 || height <= 0)
+        return 0;
+
+    rect->x = x;
+    rect->y = y;
+    rect->w = width;
+    rect->h = height;
